with rollup_totals as (select dim.status, a.txn_type, count(*) as cnt, min(a.amount) as min_amount from transactions a inner join accounts dim on a.account_id = dim.id group by rollup (dim.status, a.txn_type)) select txn_type, min_amount, case when txn_type rlike '^(CREDIT|REFUND)$' then 'OTHER_ZONE' when txn_type rlike '^(DEBIT|FEE)$' then 'GROUP_B' else 'GROUP_A' end as txn_type_zone from rollup_totals order by txn_type_zone asc, txn_type desc
